def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    two=[(i,j) for i in range(h) for j in range(w) if g[i][j]==2]
    shape=[(i,j,g[i][j]) for i in range(h) for j in range(w) if g[i][j] not in (bg,2)]
    out=[[bg]*w for _ in range(h)]
    if len(set(i for i,_ in two))==1:   # horizontal 2-line -> move vertically until adjacent
        row=two[0][0]
        above=all(i<=row-1 for i,_ in shape)
        below=all(i>=row+1 for i,_ in shape)
        if above and below:
            step=-1*(max(i for i,_ in shape)-row)  # move up until top of shape at row-? actually top just above line
        elif above:
            step=row-max(i for i,_ in shape)-1
        elif below:
            step=min(i for i,_ in shape)-row-1
        else:
            step = -1 if min(i for i,_ in shape)==row else None
        assert step is not None
        for i,j,v in shape:
            out[i+step][j]=v
    else:
        col=two[0][1]
        leftall=all(j<=col-1 for _,j,_ in shape)
        rightall=all(j>=col+1 for _,j,_ in shape)
        if leftall and rightall:
            step=-(max(j for _,j,_ in shape)-col)
        elif leftall:
            step=col-max(j for _,j,_ in shape)-1
        elif rightall:
            step=min(j for _,j,_ in shape)-col-1
        else:
            step=None
        assert step is not None
        for i,j,v in shape:
            out[i][j+step]=v
    return out
